    ('1df99ff7-6cb9-56a9-8e17-6ee57327cf4a'::uuid, 'Quiz — Les deux fonctions qui reviennent sur elles-mêmes', 'Maths', 'Tle', 'Fonctions cosinus et sinus', 'd5042244-aeb2-5673-b5d3-d4e65fb61ff7'::uuid),
